mapper.sql:

V.PERSON_ID = H.PERSON_ID
AND H.DEPTNO = ACC.DEPTNO
AND H.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
AND H.EMPID NOT LIKE '111111%'
AND V.AR_MONTH_STR = #{arMonth, jdbcType=VARCHAR}

    AND (
        UPPER(H.EMPID) LIKE '%' || UPPER(#{keyword, jdbcType=VARCHAR}) || '%'
        OR CONVERTTOUNSIGN(UPPER(H.LOCAL_NAME)) LIKE '%' || CONVERTTOUNSIGN(UPPER(#{keyword, jdbcType=VARCHAR})) || '%'
    )


    AND INSTR(',' || #{deptNos, jdbcType=VARCHAR} || ',', ',' || H.DEPTNO || ',') > 0

mapper.select:
SELECT * FROM (
    SELECT INNER_Q.*, ROWNUM AS RN FROM (
        SELECT 
        FROM V_HR_OT_REPORT V, HR_EMPLOYEE H, 
        WHERE 
        ORDER BY H.EMPID ASC
    ) INNER_Q
    WHERE ROWNUM <= #{start, jdbcType=INTEGER} + #{length, jdbcType=INTEGER}
) WHERE RN > #{start, jdbcType=INTEGER}
